@ToolMeta(name="edt_editor_scroll",category="workspace",tags={"workspace","edt"})
public final class EdtEditorScrollTool extends AbstractEdtEditorTool {
    public EdtEditorScrollTool(){super("scroll","Scroll an explicit target returned by edt_editor_regions. preview uses outer pixels; preview_content uses vertical wheel notches with positive amount moving down and supports only operation=by, at most 30 notches. Other targets support by/page/start/end; by uses pixel deltas (converted to rows for trees/tables), page uses signed page count. capture=true returns a PNG plus before/after results. Native end_reached is unknown, never inferred from unchanged image. Does not change/save the form model.","{\"type\": \"object\", \"additionalProperties\": false, \"properties\": {\"editor_id\": {\"type\": \"string\"}, \"target\": {\"type\": \"string\"}, \"axis\": {\"type\": \"string\", \"enum\": [\"vertical\", \"horizontal\"], \"default\": \"vertical\"}, \"operation\": {\"type\": \"string\", \"enum\": [\"by\", \"page\", \"start\", \"end\"], \"default\": \"by\"}, \"amount\": {\"type\": \"integer\", \"minimum\": -10000, \"maximum\": 10000}, \"capture\": {\"type\": \"boolean\", \"default\": false}, \"auto_restore\": {\"type\": \"boolean\", \"default\": true}}, \"required\": [\"editor_id\", \"target\"]}");}
}
